def _check_sse_field_single_line(v: str | None) -> str | None:
    if v is not None and ("\n" in v or "\r" in v or "\0" in v):
        raise ValueError("SSE field must be a single line and must not contain null characters.")
    return v

arguments.old_string:
def _check_id_no_null(v: str | None) -> str | None:
    if v is not None and "\\0" in v:
        raise ValueError("SSE 'id' must not contain null characters")
    return v

