from fastapi.sse import ServerSentEvent

def test_sse_validation():
    print("--- Testing SSE Validation ---")

    # 1. Valid input
    try:
        event1 = ServerSentEvent(id="123", event="test", data="valid")
        print("Test 1 (Valid input): PASSED")
    except Exception as e:
        print(f"Test 1 (Valid input): FAILED with {e}")

    # 2. Invalid id with newline
    try:
        ServerSentEvent(id="123\n456", event="test", data="valid")
        print("Test 2 (Invalid id with newline): FAILED (Expected ValueError)")
    except ValueError as e:
        print(f"Test 2 (Invalid id with newline): PASSED (Caught expected error: {e})")
    except Exception as e:
        print(f"Test 2 (Invalid id with newline): FAILED (Caught wrong exception: {e})")

    # 3. Invalid event with newline
    try:
        ServerSentEvent(id="123", event="test\nnewline", data="valid")
        print("Test 3 (Invalid event with newline): FAILED (Expected ValueError)")
    except ValueError as e:
        print(f"Test 3 (Invalid event with newline): PASSED (Caught expected error: {e})")
    except Exception as e:
        print(f"Test 3 (Invalid event with newline): FAILED (Caught wrong exception: {e})")

    # 4. Invalid input with null character (id)
    try:
        ServerSentEvent(id="123\0456", event="test", data="valid")
        print("Test 4 (Invalid id with null char): FAILED (Expected ValueError)")
    except ValueError as e:
        print(f"Test 4 (Invalid id with null char): PASSED (Caught expected error: {e})")
    except Exception as e:
        print(f"Test 4 (Invalid id with null char): FAILED (Caught wrong exception: {e})")

if __name__ == "__main__":
    test_sse_validation()
PY
